use std::sync::{Arc, Mutex};
use std::thread;

fn w1(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let _guard_a = a.lock().unwrap();
    let _guard_b = b.lock().unwrap();
}

fn w2(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let _guard_a = a.lock().unwrap();
    let _guard_b = b.lock().unwrap();
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let worker1 = thread::spawn(w1, Arc::clone(&a), Arc::clone(&b));
    let worker2 = thread::spawn(w2, Arc::clone(&a), Arc::clone(&b));

    worker1.join().unwrap();
    worker2.join().unwrap();

    println!("DONE done=1");
}
